// O(1) direct-array lookup — threaded-cache-safe function-local static
static inline signed char get_cell_lane_fast(int loc) {
    if (loc < 0 || loc >= LANE_CELL_COUNT) return -1;
    static signed char* table = nullptr;
    if (!table) {
        table = new signed char[LANE_CELL_COUNT];
        int pos = 0;
        for (int ri = 0; ri < LANE_CELL_RLE_COUNT; ri++) {
            for (int c = 0; c < g_cell_lane_rle[ri].count; c++)
                table[pos++] = g_cell_lane_rle[ri].val;
        }
    }
    return table[loc];
}

// O(1) direct-array lookup for core bottleneck cells
static inline signed char get_cell_core_fast(int loc) {
    if (loc < 0 || loc >= LANE_CELL_COUNT) return -1;
    static signed char* table = nullptr;
    if (!table) {
        table = new signed char[LANE_CELL_COUNT];
        int pos = 0;
        for (int ri = 0; ri < CORE_CELL_RLE_COUNT; ri++) {
            for (int c = 0; c < g_cell_core_rle[ri].count; c++)
                table[pos++] = g_cell_core_rle[ri].val;
        }
    }
    return table[loc];
}

// Legacy O(n) lookup retained for compatibility
static inline int get_cell_lane(int loc) {
    if (loc < 0 || loc >= LANE_CELL_COUNT) return -1;
    int pos = 0;
    for (int ri = 0; ri < LANE_CELL_RLE_COUNT; ri++) {
        pos += g_cell_lane_rle[ri].count;
        if (loc < pos) return g_cell_lane_rle[ri].val;
    }
    return -1;
}
